// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner, address ownerActor) public {
        vm.assume(ownerActor != address(0));

        vm.deal(ownerActor, 1 ether);

        bool ok;
        try c.setOwner(ownerActor) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok);

        bool ret;
        vm.prank(ownerActor);
        try c.setOwner(newOwner) returns (bool r) {
            ret = r;
        } catch {
            revert("unexpected revert from setOwner when called by current owner");
        }

        assertTrue(ret);
    }
}
